REGISTER STORAGE UNIT ds_0 (URL='jdbc:h2:mem:distsql_rdl_bootstrap',USER='sa',PASSWORD='',PROPERTIES('driverClassName'='org.h2.Driver'));
            CREATE SHARDING TABLE RULE t_order (STORAGE_UNITS(ds_0),SHARDING_COLUMN=user_id,TYPE(NAME='MOD',PROPERTIES('sharding-count'='1')),KEY_GENERATE_STRATEGY(COLUMN=order_id,TYPE(NAME='SNOWFLAKE')));
            CREATE TABLE t_order (order_id BIGINT PRIMARY KEY,user_id INT);
